import UIKit

struct DynamicColorFactory {
    static func makeAdaptiveColor() -> UIColor {
        return UIColor { traits in
            traits.userInterfaceStyle == .dark ? .white : .black
        }
    }
}

let dynColor = DynamicColorFactory.makeAdaptiveColor()
let darkTrait = UITraitCollection(userInterfaceStyle: .dark)
print("Dark is white: \(dynColor.resolvedColor(with: darkTrait) == .white)")

import UIKit

class AccessibleLabelFactory {
    @MainActor
    static func makeAccessibleLabel(textStyle: UIFont.TextStyle) -> UILabel {
        let label = UILabel()
        label.font = UIFont.preferredFont(forTextStyle: textStyle)
        label.adjustsFontForContentSizeCategory = true
        label.numberOfLines = 0
        return label
    }
}

let testLabel = AccessibleLabelFactory.makeAccessibleLabel(textStyle: .body)
print("Label configured: \(testLabel.adjustsFontForContentSizeCategory && testLabel.numberOfLines == 0)")

import UIKit

struct CustomFontScaler {
    static func scaleCustomFont(size: CGFloat, textStyle: UIFont.TextStyle) -> UIFont {
        let baseFont = UIFont.systemFont(ofSize: size)
        let metrics = UIFontMetrics(forTextStyle: textStyle)
        return metrics.scaledFont(for: baseFont)
    }
}

let customFont = CustomFontScaler.scaleCustomFont(size: 18, textStyle: .headline)
print("Font point size: \(Int(customFont.pointSize))")
